def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)
    if all((ch == '9' for ch in s)):
        return num + 2

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    def mirror_left_to_right(left: str, length: int) -> str:
        if length % 2 == 0:
            return left + left[::-1]
        else:
            return left + left[-2::-1]
    half_len = (length + 1) // 2
    left = s[:half_len]
    palindrome = mirror_left_to_right(left, length)
    palindrome_num = int(palindrome)
    if palindrome_num > num:
