def get_total_number_of_sequences(n, M):
    """
    Returns the number of sequences of length n where each element is an integer
    between 1 and M (inclusive), and each next element is greater than or equal to
    twice the previous element.

    Parameters:
    - n: int, length of the sequence
    - M: int, maximum allowed value for any element

    Returns:
    - int, total number of such sequences
    """
    if n == 0:
        return 0
    if n == 1:
        return M
    dp = [[0] * (M + 1) for _ in range(n)]
    for x in range(1, M + 1):
        dp[0][x] = 1
    for i in range(1, n):
        prefix = [0] * (M + 1)
        for x in range(1, M + 1):
            prefix[x] = prefix[x - 1] + dp[i - 1][x]
        for x in range(1, M + 1):
            max_prev = x // 2
            if max_prev >= 1:
                dp[i][x] = prefix[max_prev]
            else:
                dp[i][x] = 0
    return sum(dp[n - 1][1:])

