    def all_nines(num_str):
        return all((ch == '9' for ch in num_str))
    if all_nines(s):
        return int('1' + '0' * (length - 1) + '1')
    num = list(s)
    mid = length // 2
    left_end = mid - 1
    right_start = mid + 1 if length % 2 else mid
    while left_end >= 0:
        num[right_start] = num[left_end]
        left_end -= 1
        right_start += 1
    palindrome = int(''.join(num))
    if palindrome > n:
