def sort_sublists(list_of_lists):

    def sort_key(s):
        return s
    for sublist in list_of_lists:
        from collections import defaultdict, deque
        n = len(sublist)
        graph = defaultdict(list)
        for i in range(n):
            for j in range(i + 1, n):
                s1, s2 = (sublist[i], sublist[j])
                if s1.startswith(s2) or s2.startswith(s1):
                    graph[i].append(j)
                    graph[j].append(i)
        visited = [False] * n
        groups = []
        for i in range(n):
            if not visited[i]:
                queue = deque([i])
                visited[i] = True
                component = []
                while queue:
                    u = queue.popleft()
                    component.append(u)
                    for v in graph[u]:
                        if not visited[v]:
                            visited[v] = True
                            queue.append(v)
                groups.append(component)

        def group_key(indices):
            return min((sublist[i] for i in indices))
        groups.sort(key=group_key)
        for g in groups:
            g.sort()
        sorted_sublist = []
        for g in groups:
            for i in g:
