def find_solution(a, b, n):
    """
    Find non-negative integers x, y such that a*x + b*y = n.
    Returns a tuple (x, y) if a solution exists, else None.
    """
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        gcd, s1, t1 = extended_gcd(y, x % y)
        s = t1
        t = s1 - x // y * t1
        return (gcd, s, t)
    gcd, x0, y0 = extended_gcd(a, b)
    if n % gcd != 0:
        return None
    x0 *= n // gcd
    y0 *= n // gcd
    b_div = b // gcd
    a_div = a // gcd
    k_min = (-x0 + b_div - 1) // b_div
    k_max = y0 // a_div
    if k_min > k_max:
        return None
    k = k_min
    x = x0 + k * b_div
    y = y0 - k * a_div
    if x < 0 or y < 0:
        return None
    return (x, y)

