def smallest_missing(arr, low, high):
    """
    Find the smallest non-negative integer that does not appear in arr[low:high+1],
    but must be an integer that actually appears somewhere in arr[low:high+1].

    Parameters:
    arr (list of int): Sorted array of distinct non-negative integers.
    low (int): Lower index bound (inclusive).
    high (int): Upper index bound (inclusive).

    Returns:
    int or None: The smallest missing integer that appears in the subarray,
                 or None if no such missing integer exists.
