def next_smallest_palindrome(num: int) -> int:
    """
    Find the smallest palindrome strictly greater than `num`.
    """
    s = str(num)
    length = len(s)
    if length == 1:
        return num + 1 if num < 9 else 11

    def is_all_nines(s):
        return all((ch == '9' for ch in s))
    if is_all_nines(s):
        return int('1' + '0' * (length - 1) + '1')

    def make_palindrome(left, length):
        if length % 2 == 0:
            return left + left[::-1]
        else:
            return left + left[:-1][::-1]
    half_len = (length + 1) // 2
    left_half = s[:half_len]
    palindrome = make_palindrome(left_half, length)
    if int(palindrome) > num:
        return int(palindrome)
    incremented = str(int(left_half) + 1)
    if len(incremented) > len(left_half):
        return int(incremented + incremented[:-1][::-1]) if length % 2 else int(incremented + incremented[::-1])
