def next_smallest_palindrome(num: int) -> int:
    """
    Return the smallest palindrome strictly greater than the input number.
    """
    s = str(num)
    length = len(s)

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    def make_palindrome(left: str, odd_length: bool) -> str:
        if odd_length:
            return left + left[:-1][::-1]
        else:
            return left + left[::-1]
    if num < 9:
        return num + 1
    odd_length = length % 2 != 0
    half_len = (length + 1) // 2
    left = s[:half_len]
    palindrome = int(make_palindrome(left, odd_length))
    if palindrome > num:
        return palindrome
    left_int = int(left)
    left_int += 1
    left = str(left_int)
    if len(left) > half_len:
