def remove_column(collection, index):
    """
    Remove the element at position `index` from each inner grouping within a multi-level collection.

    Args:
        collection: A multi-level collection (e.g., list of lists).
        index: The position of the element to remove from each inner grouping.

    Returns:
        A new collection with the specified column removed from each inner grouping.
        Inner groupings shorter than or equal to `index` are left unchanged.
    """
    result = []
    for inner in collection:
        if isinstance(inner, (list, tuple)):
            if len(inner) > index:
                if isinstance(inner, list):
                    new_inner = inner[:index] + inner[index + 1:]
                else:
                    new_inner = inner[:index] + inner[index + 1:]
                if isinstance(inner, tuple):
