def compute_Last_Digit(a: int, b: int) -> int:
    """
    Compute the last digit of (b! / a!) assuming a! divides b! exactly.
    Since b! / a! = (a+1) * (a+2) * ... * b,
    we just multiply these numbers and find the last digit.
