def dif_Square(n: int) -> bool:
    """
    Check whether the integer n can be represented as a difference of two squares:
    n = a^2 - b^2, for some integers a, b.

    Returns True if such integers exist, False otherwise.
    """
    if n == 0:
        return True
    abs_n = abs(n)
    from math import isqrt
    for x in range(1, isqrt(abs_n) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            if n > 0:
                if (x + y) % 2 == 0:
                    return True
                if (-x + -y) % 2 == 0:
                    return True
