def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)
    if all((ch == '9' for ch in s)):
        return int('1' + '0' * (length - 1) + '1')
    arr = list(s)

    def mirror_left_to_right(arr):
        n = len(arr)
        mid = n // 2
        left_end = mid - 1
        right_start = mid + 1 if n % 2 else mid
        while left_end >= 0:
            arr[right_start] = arr[left_end]
            left_end -= 1
            right_start += 1
    mirror_left_to_right(arr)
    palindrome = int(''.join(arr))
    if palindrome > num:
        return palindrome
    n = length
    mid = n // 2
    if n % 2 == 1:
        i = mid
        while i >= 0:
            if arr[i] != '9':
                arr[i] = str(int(arr[i]) + 1)
                break
            else:
                arr[i] = '0'
                i -= 1
        if i < 0:
            arr = ['1'] + ['0'] * (n - 1) + ['1']
            return int(''.join(arr))
    else:
        i = mid - 1
        j = mid
        while i >= 0:
            if arr[i] != '9':
                val = int(arr[i]) + 1
                arr[i] = str(val)
                arr[j] = str(val)
                break
            else:
                arr[i] = arr[j] = '0'
                i -= 1
                j += 1
        if i < 0:
            arr = ['1'] + ['0'] * (n - 1) + ['1']
            return int(''.join(arr))
