def find_solution(a, b, n):
    """
    Find nonnegative integers x, y such that a*x + b*y = n.
    If no such pair exists, return None.

    Parameters:
    a (int): coefficient of x (should be positive)
    b (int): coefficient of y (should be positive)
    n (int): target integer

    Returns:
    tuple or None: (x, y) with x, y >= 0 and a*x + b*y = n, or None if no solution.
