def find_Max(arr):
    """
    Find the maximum element in a sorted and rotated array with distinct elements.
    If the array is not rotated (fully sorted), return the last element.

    :param arr: List[int] - a non-empty list of distinct integers
    :return: int - the maximum element in the array
